import{_ as o,o as e,c as d,ai as r}from"./chunks/framework.CAnUr3M0.js";const g=JSON.parse('{"title":"CSS 工程化","description":"","frontmatter":{},"headers":[],"relativePath":"css/engineering.md","filePath":"css/engineering.md"}'),s={name:"css/engineering.md"};function n(i,t,l,a,c,S){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="css-工程化" tabindex="-1">CSS 工程化 <a class="header-anchor" href="#css-工程化" aria-label="Permalink to &quot;CSS 工程化&quot;">​</a></h1><blockquote><p>预处理器 · Icon 技术 · 性能优化 · Sprites</p></blockquote><hr><h2 id="_1-css-预处理器-后处理器" tabindex="-1">1. CSS 预处理器 / 后处理器 <a class="header-anchor" href="#_1-css-预处理器-后处理器" aria-label="Permalink to &quot;1. CSS 预处理器 / 后处理器&quot;">​</a></h2><p><strong>预处理器</strong>（Less/Sass/Stylus）：</p><ul><li>为 CSS 增加编程特性：变量、嵌套、mixin、循环、函数</li><li>编译为 CSS 后使用</li><li>好处：结构清晰、便于扩展、屏蔽浏览器差异</li></ul><p><strong>后处理器</strong>（PostCSS）：</p><ul><li>处理 CSS 本身（类似 Babel 对 JS 的作用）</li><li>常用场景：Autoprefixer 自动加浏览器前缀</li></ul><p><strong>CSS 工程化三个方向</strong>：预处理器（Less/Sass）、PostCSS 插件、Webpack loader</p><hr><h2 id="_2-icon-技术演进" tabindex="-1">2. Icon 技术演进 <a class="header-anchor" href="#_2-icon-技术演进" aria-label="Permalink to &quot;2. Icon 技术演进&quot;">​</a></h2><p><strong>发展历程</strong>：img 图片 → CSS Sprites → Font Awesome → iconfont</p><p><strong>iconfont 三种使用方式</strong>：</p><table tabindex="0"><thead><tr><th>方式</th><th>兼容性</th><th>多色</th><th>特点</th></tr></thead><tbody><tr><td><strong>unicode</strong></td><td>IE6+</td><td>❌</td><td>兼容性最好，书写不直观</td></tr><tr><td><strong>font-class</strong></td><td>IE8+</td><td>❌</td><td>语意明确（<code>.icon-QQ</code>）</td></tr><tr><td><strong>symbol</strong></td><td>IE9+</td><td>✅</td><td>支持多色、SVG 矢量、可用 CSS 动画</td></tr></tbody></table><p><strong>Inline SVG vs Icon Font</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>Icon Font</th><th>Inline SVG</th></tr></thead><tbody><tr><td>矢量</td><td>当文本处理，会抗锯齿</td><td>真正矢量，清晰锐利</td></tr><tr><td>CSS 控制</td><td>font-size/颜色</td><td>同上，且可控制各部分</td></tr><tr><td>定位</td><td>依赖行内属性</td><td>显示尺寸就是本身尺寸</td></tr><tr><td>可靠性</td><td>可能跨域/加载失败</td><td>内联在文档流，无风险</td></tr><tr><td>兼容性</td><td>IE6+</td><td>IE9+</td></tr></tbody></table><p><strong>结论</strong>：只需兼容 IE9+ → <strong>inline SVG 几乎全面优于 icon font</strong></p><hr><h2 id="_3-css-sprites-精灵图" tabindex="-1">3. CSS Sprites（精灵图） <a class="header-anchor" href="#_3-css-sprites-精灵图" aria-label="Permalink to &quot;3. CSS Sprites（精灵图）&quot;">​</a></h2><ul><li>将所有小图标合并到一张大图，通过 <code>background-position</code> 定位</li><li><strong>优点</strong>：减少 HTTP 请求、减少图片总字节</li><li><strong>缺点</strong>：合并麻烦、定位需测量、维护困难</li></ul><hr><h2 id="_4-css-性能优化" tabindex="-1">4. CSS 性能优化 <a class="header-anchor" href="#_4-css-性能优化" aria-label="Permalink to &quot;4. CSS 性能优化&quot;">​</a></h2><p><strong>选择器匹配机制（从右向左）</strong>：</p><ul><li>浏览器解析选择器时从右向左匹配</li><li>最右侧部分决定匹配效率，应尽可能精确</li></ul><p><strong>加载性能</strong>：</p><ul><li>CSS 压缩、减少 <code>@import</code>（用 <code>link</code> 代替）</li><li>避免通配符选择器 <code>*</code></li><li>选择器层级不超过三层，多用 class 少用标签</li></ul><p><strong>渲染性能</strong>：</p><ul><li>减少重排重绘（避免频繁读取 <code>offset*</code>/<code>scroll*</code>/<code>client*</code>）</li><li>去除空规则、属性值 0 不加单位</li><li>CSS 雪碧图（小图标）</li><li>减少昂贵属性：<code>box-shadow</code>、<code>border-radius</code>、<code>filter</code>、<code>:nth-child</code></li><li><code>will-change</code> 提前告知浏览器（不可滥用）</li></ul>',28)])])}const p=o(s,[["render",n]]);export{g as __pageData,p as default};
